/**
 * Model User
 * Base user profile linked to Clerk authentication identity.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Organization
 * An operational entity participating in SaveByte.
 * (e.g. Restaurant, Hotel, Kitchen, NGO, Food Bank, Logistics, Recovery Partner)
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model Facility
 * Physical operational location / facility under an Organization.
 * Holds operational coordinates (lat/long) and address details.
 */
export type Facility = $Result.DefaultSelection<Prisma.$FacilityPayload>
/**
 * Model Membership
 * Relationship between a User and an Organization with role and lifecycle status.
 */
export type Membership = $Result.DefaultSelection<Prisma.$MembershipPayload>
/**
 * Model OrganizationApplication
 * Organization Application for Industry and NGO onboarding before approval.
 */
export type OrganizationApplication = $Result.DefaultSelection<Prisma.$OrganizationApplicationPayload>
/**
 * Model AuditLog
 * Append-Only Audit Log for security and governance.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model FoodItem
 * Reusable Food Catalog Item owned by a producing Organization.
 */
export type FoodItem = $Result.DefaultSelection<Prisma.$FoodItemPayload>
/**
 * Model FoodBatch
 * A specific production batch of a FoodItem at a Facility.
 */
export type FoodBatch = $Result.DefaultSelection<Prisma.$FoodBatchPayload>
/**
 * Model InventoryTransaction
 * Traceable append-style inventory ledger transaction.
 */
export type InventoryTransaction = $Result.DefaultSelection<Prisma.$InventoryTransactionPayload>
/**
 * Model SurplusListing
 * Surplus food posted by a donor organization facility for recovery.
 */
export type SurplusListing = $Result.DefaultSelection<Prisma.$SurplusListingPayload>
/**
 * Model FoodRequest
 * Request for food from an NGO or individual community member.
 */
export type FoodRequest = $Result.DefaultSelection<Prisma.$FoodRequestPayload>
/**
 * Model RecoveryTransaction
 * Central recovery / fulfillment transaction connecting Donor, Recipient, Food, and Handover lifecycle.
 */
export type RecoveryTransaction = $Result.DefaultSelection<Prisma.$RecoveryTransactionPayload>
/**
 * Model MatchRecommendation
 * Explainable matching recommendation between surplus food and eligible recipients / requests.
 */
export type MatchRecommendation = $Result.DefaultSelection<Prisma.$MatchRecommendationPayload>
/**
 * Model Vehicle
 * Logistics fleet vehicle for surplus pickup and delivery.
 */
export type Vehicle = $Result.DefaultSelection<Prisma.$VehiclePayload>
/**
 * Model DeliveryRoute
 * Delivery route / pickup assignment linking recovery to physical transport.
 */
export type DeliveryRoute = $Result.DefaultSelection<Prisma.$DeliveryRoutePayload>
/**
 * Model AIInsight
 * Cached intelligence insights, predictions, audits, and recommendations.
 */
export type AIInsight = $Result.DefaultSelection<Prisma.$AIInsightPayload>

